// Before
public decimal Calc(List<Enrollment> l)
{
    decimal t = 0;
    foreach (var e in l) if (e.Grade != null) t += e.Grade.Value * e.Course.Hours;
    var h = l.Where(e => e.Grade != null).Sum(e => e.Course.Hours);
    return h == 0 ? 0 : t / h;
}

// After: same behaviour, clear names
public decimal WeightedAverage(List<Enrollment> enrollments)
{
    var graded = enrollments.Where(e => e.Grade is not null).ToList();
    var hours = graded.Sum(e => e.Course.Hours);
    return hours == 0 ? 0 : graded.Sum(e => e.Grade!.Value * e.Course.Hours) / (decimal)hours;
}

