public interface IEnrollmentStore
{
    Task<Course?> FindCourseAsync(int id, CancellationToken ct);
    Task AddAsync(Enrollment enrollment, CancellationToken ct);
}

public class EnrollStudent(IEnrollmentStore store, IEmailSender email)
{
    public async Task<string?> RunAsync(int studentId, int courseId, CancellationToken ct)
    {
        var course = await store.FindCourseAsync(courseId, ct);
        if (course is null) return "Course not found";
        if (course.IsFull) return "The course is full";
        await store.AddAsync(new Enrollment(studentId, courseId), ct);
        await email.SendAsync(studentId, $"You are enrolled in {course.Title}");
        return null;
    }
}

