// The registrar's words, in the code
public class Section
{
    public Course Course { get; private set; } = null!;
    public Term Term { get; private set; } = null!;
    public int Capacity { get; private set; }
    public IReadOnlyList<Enrollment> Enrollments => enrollments;
    private readonly List<Enrollment> enrollments = [];
}

public record Grade
{
    public int Value { get; }
    public Grade(int value)
    {
        if (value is < 0 or > 100) throw new ArgumentOutOfRangeException(nameof(value));
        Value = value;
    }
}

public partial class Section   // the aggregate root
{
    public Enrollment Enroll(StudentId student)
    {
        if (enrollments.Count >= Capacity) throw new DomainException("The section is full.");
        if (enrollments.Any(e => e.Student == student)) throw new DomainException("Already enrolled.");
        var enrollment = new Enrollment(student);
        enrollments.Add(enrollment);
        return enrollment;
    }
}

